import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int h = nextInt(), w = nextInt(), r = nextInt();
        long[][] a = new long[h][w], p = new long[h + 1][w + 1];
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++) {
                a[i][j] = nextLong();
                p[i + 1][j + 1] = a[i][j] + p[i][j + 1] + p[i + 1][j] - p[i][j];
            }
        long d = 2L * r + 1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                long v = a[i][j];
                if (i >= r && i < h - r && j >= r && j < w - r)
                    v = (p[i + r + 1][j + r + 1] - p[i - r][j + r + 1] - p[i + r + 1][j - r] + p[i - r][j - r]) / (d * d);
                if (j > 0) sb.append(' ');
                sb.append(v);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	h, w, r := nextInt(), nextInt(), nextInt()
	a := make([][]int, h)
	p := make([][]int, h+1)
	p[0] = make([]int, w+1)
	for i := 0; i < h; i++ {
		a[i] = make([]int, w)
		p[i+1] = make([]int, w+1)
		for j := 0; j < w; j++ {
			a[i][j] = nextInt()
			p[i+1][j+1] = a[i][j] + p[i][j+1] + p[i+1][j] - p[i][j]
		}
	}
	d := 2*r + 1
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			v := a[i][j]
			if i >= r && i < h-r && j >= r && j < w-r {
				v = (p[i+r+1][j+r+1] - p[i-r][j+r+1] - p[i+r+1][j-r] + p[i-r][j-r]) / (d * d)
			}
			if j > 0 {
				out.WriteByte(' ')
			}
			out.WriteString(strconv.Itoa(v))
		}
		out.WriteByte('\n')
	}
}
